from pathlib import Path
import json
import numpy as np,pandas as pd
OUT=(Path(__import__('os').environ['CRRM_WORKSPACE']) / 'clinical_otherwisehealthy_262_r1/main');read=lambda f:pd.read_csv(OUT/'tables'/f);spec=[]
def add(sheet,title,d,notes):
 file=sheet+'.csv';d.to_csv(OUT/'tables'/file,index=False);spec.append(dict(sheet=sheet,title=title,file=file,notes=notes))
rows=[]
def primary_row(source,analysis,contrast,units,measured,r,adj=np.nan,family='',resamp=np.nan,resampadj=np.nan):
 rows.append({'Source':source,'Analysis':analysis,'Comparison':contrast,'Analysis units':units,'Scored members':measured,'Mean score change':r['effect'],'95% CI lower':r['CI95_low'],'95% CI upper':r['CI95_high'],'Model P':r['p_value'],'Adjusted P':adj,'Adjustment family':family,'Resampling P':resamp,'Resampling adjusted P':resampadj})
effects=read('09_total_clinical_effects.csv')
for _,r in effects.iterrows():primary_row(r.dataset,'Primary strict severity' if r.role=='Primary' else 'Hospitalization sensitivity',f'{r.positive} minus {r.reference}',f'{r.n_positive} / {r.n_reference} acute samples',r.n_measured,r,r.primary_Holm_P,'Holm: 2 primary strict-severity tests' if r.role=='Primary' else 'Secondary; separate endpoint',r.resampling_P,r.resampling_Holm_P)
coverage=read('06_coverage_summary.csv').set_index('dataset')
for _,r in read('17_covariate_adjusted_effects.csv').iterrows():
 covariates=r.covariates if isinstance(r.covariates,str) else 'None'
 primary_row(r.dataset,'Secondary HC3 model: '+r.model,'Severe minus Mild' if r.dataset=='GSE246622' else 'Inpatient minus Outpatient',f'{r.n} acute samples;'+covariates,int(coverage.loc[r.dataset,'n_scored']),r,r.adjusted_model_BH2_P,'BH: 2 adjusted total-score models' if r.model=='adjusted' else 'Unadjusted same-sample comparator')
r=read('19_paired_recovery_effects.csv').query('metric == "Total"').iloc[0];primary_row('GSE69606','Paired recovery','Recovery minus acute','15 verified donor pairs',357,r,family='Single planned secondary total-score comparison',resamp=r.exact_signflip_P)
r=read('23_RMA_source_sensitivity.csv').iloc[0];primary_row('GSE246622','RMA-only source sensitivity','Severe minus Mild',f'{int(r.n_positive)} / {int(r.n_reference)} acute profiles',int(r.n_measured),r,family='Source sensitivity; not an additional cohort')
add('S3A_Clinical_effects','Table S3A. Clinical associations and paired recovery of the frozen CRRM',pd.DataFrame(rows),[
 'The two primary strict Severe-minus-Mild tests use Welch inference and Holm adjustment. Neither met the prespecified Holm criterion. Resampling sensitivities retain the same two-test family. Hospitalization is a distinct secondary endpoint and is not pooled with clinical severity grades.',
 'Covariate-adjusted models are secondary and use HC3 standard errors on the same samples as their unadjusted model comparator. GSE246622 adjusts for a three-df natural age spline and sex; GSE105450 adjusts for age, sex, and original study stratum. Individual age/sex are unavailable for GSE69606.',
 'Scores use within-dataset gene z scores with fixed signs and equal per-gene weights. Changes have dataset-relative units; they are not an absolute cross-platform scale. GSE246622 uses 313 healthy/acute profiles; GSE105450 uses 89 RSV cases; GSE69606 uses 26 acute profiles and projects recovery onto this same reference.',
 'GSE246622 uses author batch-corrected processed values; RMA-only sensitivity is the same study family (score correlation 0.993928). Healthy technical-control replicates from GSE105450 are outside the hospitalization analysis. Paired recovery is the same GSE69606 study family, not an independent cohort.'
])
b=read('10_functional_clinical_effects.csv');rows=[]
for _,r in b.iterrows():rows.append({'Source':r.dataset,'Analysis':r.role,'Comparison':f'{r.positive} minus {r.reference}','Fixed branch':r.branch,'Scored branch members':r.n_measured_branch,'Frozen branch members':r.n_frozen,'Mean branch score change':r.effect,'95% CI lower':r.CI95_low,'95% CI upper':r.CI95_high,'Model P':r.p_value,'BH-adjusted P':r.BH_adjusted_P,'Adjustment family':r.adjustment_family,'Exact sign-flip P':np.nan,'Exact sign-flip BH P':np.nan})
fc=read('08_functional_branch_coverage.csv')
for _,r in read('19_paired_recovery_effects.csv').query('metric != "Total"').iterrows():
 c=fc[fc.dataset.eq('GSE69606')&fc.branch.eq(r.metric)].iloc[0];rows.append({'Source':'GSE69606','Analysis':'Paired recovery','Comparison':'Recovery minus acute','Fixed branch':r.metric,'Scored branch members':c.n_measured,'Frozen branch members':c.n_frozen,'Mean branch score change':r.effect,'95% CI lower':r.CI95_low,'95% CI upper':r.CI95_high,'Model P':r.p_value,'BH-adjusted P':r.branch_BH7_P,'Adjustment family':'BH7 recovery branches','Exact sign-flip P':r.exact_signflip_P,'Exact sign-flip BH P':r.branch_signflip_BH7_P})
for _,r in read('30_covariate_adjusted_branch_sensitivity.csv').iterrows():rows.append({'Source':r.dataset,'Analysis':'Additional exploratory covariate sensitivity (HC3)','Comparison':'Severe minus Mild' if r.dataset=='GSE246622' else 'Inpatient minus Outpatient','Fixed branch':r.branch,'Scored branch members':r.n_measured_branch,'Frozen branch members':r.n_frozen,'Mean branch score change':r.effect,'95% CI lower':r.CI95_low,'95% CI upper':r.CI95_high,'Model P':r.p_value,'BH-adjusted P':r.BH14_adjusted_branch_sensitivity_P,'Adjustment family':'Separate BH14 adjusted functional sensitivities','Exact sign-flip P':np.nan,'Exact sign-flip BH P':np.nan})
add('S3B_Functional_responses','Table S3B. Clinical responses of seven fixed CRRM functional branches',pd.DataFrame(rows),[
 'Fixed branches overlap in membership and are not independent disjoint modules. Branch scores retain the same frozen directions and per-gene scaling as the total score. All displayed branches meet at least five genes and 50% coverage.',
 'BH families are 14 branch-by-strict-severity tests, seven hospitalization tests, and seven paired-recovery tests. Recovery sign-flip sensitivities are also adjusted over seven branches. No tests were selected by significance.',
 'The neutrophil degranulation label denotes an annotation-defined gene subset measured in bulk expression. It is not a direct neutrophil count or evidence that the PBMC signal is restricted to neutrophils.',
 'After initial clinical scoring, additional covariate sensitivities were added uniformly for all seven branches in the two cohorts with individual covariates, using the same adjusted designs as S3A and one separate BH14 family. These exploratory results do not replace the predeclared unadjusted branch tests. GSE69606 covariates were unavailable.'
])
core=pd.read_csv(OUT/'parameters/frozen_CRRM388.csv').set_index('human_ensembl');g=read('12_clinical_gene_effects.csv').pivot(index='human_ensembl',columns='dataset',values='log_expression_effect');rel=read('27_infection_severity_gene_map.csv').set_index('human_ensembl');branches=pd.read_csv(OUT/'parameters/frozen_functional_branches.csv').groupby('human_ensembl').branch.agg('; '.join)
d=core[['display_symbol','frozen_direction']].join(g.rename(columns={s:s+' raw clinical log effect' for s in g})).join(rel[['Mild_minus_Healthy_adjusted_log_effect','Severe_minus_Mild_adjusted_log_effect']]);d=d.reset_index().rename(columns={'human_ensembl':'Human Ensembl ID','display_symbol':'Gene symbol','frozen_direction':'Frozen direction','Mild_minus_Healthy_adjusted_log_effect':'GSE246622 adjusted Mild minus Healthy','Severe_minus_Mild_adjusted_log_effect':'GSE246622 adjusted Severe minus Mild'})
add('S3C_Gene_effects','Table S3C. Clinical gene effects for all 388 frozen CRRM members',d,[
 'All frozen members are retained; NA means an unavailable/unscored measurement or absent branch annotation, not zero expression. Raw clinical contrasts are Severe-minus-Mild in GSE246622 and GSE69606, and Inpatient-minus-Outpatient in GSE105450.',
 'The two adjusted gene-map columns come from one GSE246622 model including clinical group, a three-df natural age spline, and sex. Native normalized log-expression effects are not sign-reversed. No external differential-expression filter or severity-based member selection was used.',
 'Gene effects are correlated. The reported correlation interval uses profile bootstrapping; genes were not treated as independent clinical subjects.'
])
rows=[]
def context(source,analysis,group,units,metric,value,lo=np.nan,hi=np.nan,interval='Pointwise 95% model CI',p=np.nan,adj=np.nan,note=''):
 rows.append({'Source':source,'Analysis':analysis,'Subgroup or contrast':group,'Analysis units':units,'Metric':metric,'Estimate':value,'Lower bound':lo,'Upper bound':hi,'Interval meaning':interval,'Model P':p,'Adjusted P':adj,'Interpretation note':note})
for _,r in read('16_secondary_grade_comparisons.csv').iterrows():context(r.dataset,'Secondary grade contrast',r.positive+' minus '+r.reference,f'{r.n_positive} / {r.n_reference} acute samples','Mean score change',r.effect,r.CI95_low,r.CI95_high,p=r.p_value,adj=r.BH3_within_cohort,note='BH3 within cohort; primary Severe-minus-Mild Holm result is in S3A')
for _,r in read('21_common_member_sensitivity.csv').iterrows():context(r.dataset,'Common measured members',r.positive+' minus '+r.reference,f'{r.n_positive} / {r.n_reference} acute samples','Mean score change',r.effect,r.CI95_low,r.CI95_high,p=r.p_value,note=f'{int(r.n_common)} members:{int(r.n_common_up)} up,{int(r.n_common_down)} down; full-score correlation {r.full_score_correlation:.6f}; descriptive sensitivity')
for _,r in read('24_hospitalization_study_strata.csv').iterrows():context('GSE105450','Original study stratum',r.stratum,f'{r.n_positive} inpatient / {r.n_reference} outpatient','Mean score change',r.effect,r.CI95_low,r.CI95_high,p=r.p_value,note='Discovery and Validation are strata of one study family')
for _,r in read('20_recovery_initial_grade_strata.csv').iterrows():context('GSE69606','Recovery by initial grade',r.initial_group,f'{r.n_pairs} verified donor pairs','Recovery-minus-acute score',r.effect,r.CI95_low,r.CI95_high,p=r.p_value,note=f'Exploratory stratum; exact sign-flip P={r.exact_signflip_P:.8g}')
for _,r in read('26_age_sex_subgroup_effects.csv').iterrows():context(r.dataset,'Age/sex subgroup',r.variable+': '+r.level,f'{r.n_positive} / {r.n_reference} acute samples','Mean score change',r.effect,r.CI95_low,r.CI95_high,p=r.p_value,adj=r.BH4_within_cohort,note=('Age threshold '+r.age_cutoff) if isinstance(r.age_cutoff,str) else 'Secondary subgroup')
loo=read('13_patient_deletion_influence.csv');ef=effects.set_index('contrast_key')
for key,v in loo.groupby('contrast_key'):
 r=ef.loc[key];context(r.dataset,'Whole-unit deletion',r.positive+' minus '+r.reference,f'{len(v)} possible unit deletions','Full score change',r.effect,v.effect.min(),v.effect.max(),interval='Minimum-to-maximum deletion influence;not a confidence interval',note='Original gene scaling held fixed')
r=json.loads((OUT/'gene_relationship_summary.json').read_text());context('GSE246622','Adjusted infection/severity gene relationship','Mild minus Healthy versus Severe minus Mild',str(len(pd.read_csv(OUT/'data/processed/GSE246622_metadata.csv')))+' clinical profiles;'+str(r['n_genes'])+' genes','Spearman rho',r['Spearman_rho'],r['patient_bootstrap_CI95_low'],r['patient_bootstrap_CI95_high'],interval='95% percentile profile-bootstrap interval',note='1000 group-stratified profile resamples;shared Mild profiles resampled jointly;no gene-independent P')
context('GSE246622','Disjoint Mild sensitivity','Separate Mild halves for the two effects','200 balanced Mild splits with swapped roles','Median swapped-split Spearman rho',r['disjoint_split_median_rho'],r['disjoint_split_min_rho'],r['disjoint_split_max_rho'],interval='Range across split-sensitivity estimates;not a confidence interval',note='Age/sex adjusted in disjoint Healthy/Mild and Mild/Severe models; source Mild group n=79')
add('S3D_Context_sensitivity','Table S3D. Key clinical sensitivity and gene-relationship results',pd.DataFrame(rows),[
 'These secondary contrasts do not replace unsupported primary tests. Interval meaning is explicitly identified: model confidence interval, profile-bootstrap interval, or descriptive influence/split range.',
 'Age cutoffs are 90 days in GSE246622 and three months in GSE105450. Subgroup families use BH4 within each cohort; GSE69606 age/sex data were unavailable and were not imputed.',
 'The infection and severity axes share the Mild group. Joint patient bootstrap preserves this sampling dependence. Repeated disjoint Mild splits address shared-reference coupling; the split range is a sensitivity summary, not an inferential confidence interval.'
])
for item in spec:item['notes']=[]
(OUT/'parameters/workbook_spec.json').write_text(json.dumps(spec,ensure_ascii=False,indent=2)+'\n');print([(s['sheet'],len(pd.read_csv(OUT/'tables'/s['file']))) for s in spec])
